function clearScopeState(s,token){if(!s)return;s.live=false;capturedEditions.delete(token);for(const ns of[s.source,s.public,s.rawSource,s.rawPublic])if(ns){ns.files.clear();ns.dirs.clear();}s.authorities.clear();s.publicAliases?.clear();s.audioDelta=null;s.partitions=null;}
